-- SYS0014 APIs (4)
MERGE INTO SCM_ADM_API_M t USING (SELECT 'API_SYS0014_GET_AUTH_LIST' API_ID FROM DUAL) s ON (t.API_ID=s.API_ID)
 WHEN MATCHED THEN UPDATE SET API_TP_CD='POST', API_MSG_ID='MSG_API_SYS0014_AUTH_SEARCH', API_URL='P_SYS0014_GET_AUTH_LIST_M', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('API_SYS0014_GET_AUTH_LIST','POST','MSG_API_SYS0014_AUTH_SEARCH','P_SYS0014_GET_AUTH_LIST_M','Y','admin',SYSDATE,'admin',SYSDATE);
